import time

VALID_MODES = ['heat', 'cool']
TEMPERATURE_CHANGE_STEP = 1

class Thermostat:
    def __init__(self, current_temperature, target_temperature, mode):
        self._current_temperature = current_temperature
        self._target_temperature = target_temperature
        self._mode = mode

    def get_target_temperature(self):
        return self._target_temperature

    def set_target_temperature(self, temperature):
        self._target_temperature = temperature

    def get_mode(self):
        return self._mode

    def set_mode(self, mode):
        if mode in VALID_MODES:
            self._mode = mode
            return True
        return False

    def auto_set_mode(self):
        if self._current_temperature < self._target_temperature:
            self._mode = 'heat'
        else:
            self._mode = 'cool'

    def auto_check_conflict(self):
        if self._current_temperature > self._target_temperature:
            if self._mode == 'cool':
                return True
            else:
                self.auto_set_mode()
                return False
        else:
            if self._mode == 'heat':
                return True
            else:
                self.auto_set_mode()
                return False

    def _calculate_use_time(self):
        use_time = 0
        if self._mode == 'heat':
            while(self._current_temperature < self._target_temperature):
                self._current_temperature += TEMPERATURE_CHANGE_STEP
                use_time += 1
        else:
            while(self._current_temperature > self._target_temperature):
                self._current_temperature -= TEMPERATURE_CHANGE_STEP
                use_time += 1
        return use_time

    def simulate_operation(self):
        self.auto_set_mode()
        return self._calculate_use_time()

    @property
    def current_temperature(self):
        return self._current_temperature

    @current_temperature.setter
    def current_temperature(self, value):
        self._current_temperature = value

    @property
    def target_temperature(self):
        return self._target_temperature

    @target_temperature.setter
    def target_temperature(self, value):
        self._target_temperature = value

    @property
    def mode(self):
        return self._mode

    @mode.setter
    def mode(self, value):
        self._mode = value
